package mcpserver

import (
	"context"
	"fmt"
	"path/filepath"
	"sort"
	"strings"

	"github.com/burnside-project/burnside-go/manifest"

	"github.com/burnside-project/pg-cdc-core/internal/layout"
	"github.com/burnside-project/pg-cdc-core/internal/partition"
)

// buildViewDDL emits CREATE VIEW statements that map manifest tables to their
// live Parquet files. A table named "public.orders" becomes "public.orders" in
// DuckDB — same name as in Postgres, so SQL generated by an LLM looks natural.
//
// Only the live files are read: bases of the current generation plus deltas
// newer than the base epoch. Superseded generations would otherwise be
// double-counted during the window between a compaction writing a new base and
// deleting the old one.
//
// Partitioned tables are read with hive_partitioning so the business-date
// column is reconstructed from "<col>=<value>" directories (and
// __HIVE_DEFAULT_PARTITION__ maps back to NULL). A table mid-migration can have
// both layouts on disk, which DuckDB refuses to mix in one read, so the two
// sets are unioned explicitly.
func (s *server) buildViewDDL(ctx context.Context, m *manifest.Manifest) (string, error) {
	var b strings.Builder
	seen := map[string]bool{}

	names := make([]string, 0, len(m.Tables))
	for name, t := range m.Tables {
		if t.Status == "active" {
			names = append(names, name)
		}
	}
	sort.Strings(names)

	for _, name := range names {
		t := m.Tables[name]
		spec, err := s.viewFor(ctx, name, t, m.Schemas[name])
		if err != nil {
			return "", err
		}

		schema, table := splitQualified(name)
		if schema != "main" && !seen[schema] {
			fmt.Fprintf(&b, "CREATE SCHEMA IF NOT EXISTS %s; ", quoteIdent(schema))
			seen[schema] = true
		}
		fmt.Fprintf(&b, "CREATE OR REPLACE VIEW %s.%s AS SELECT * FROM %s; ",
			quoteIdent(schema), quoteIdent(table), spec)
	}
	return b.String(), nil
}

// viewFor resolves the live-file relation for one table.
func (s *server) viewFor(ctx context.Context, name string, t manifest.Table, schema manifest.Schema) (string, error) {
	files, err := s.sink.ListFiles(ctx, t.Path+"/")
	if err != nil {
		return "", fmt.Errorf("list files for %s: %w", name, err)
	}
	bases, deltas := layout.LiveFiles(t.Path, files, t.BaseEpoch)
	live := make([]string, 0, len(bases)+len(deltas))
	live = append(live, bases...)
	live = append(live, deltas...)

	if len(live) == 0 {
		return emptyRelation(t, schema), nil
	}

	var legacy, partitioned []string
	for _, f := range live {
		if layout.PartitionDirOf(t.Path, f) == "" {
			legacy = append(legacy, f)
		} else {
			partitioned = append(partitioned, f)
		}
	}

	switch {
	case len(partitioned) == 0:
		return parquetRelation(s.cfg.Storage.Path, legacy, false), nil
	case len(legacy) == 0:
		return parquetRelation(s.cfg.Storage.Path, partitioned, true), nil
	default:
		return unionRelation(
			parquetRelation(s.cfg.Storage.Path, legacy, false),
			parquetRelation(s.cfg.Storage.Path, partitioned, true)), nil
	}
}

// unionRelation combines two read_parquet relations with UNION ALL BY NAME,
// which needs each side to be a full SELECT.
func unionRelation(a, b string) string {
	return fmt.Sprintf("(SELECT * FROM %s UNION ALL BY NAME SELECT * FROM %s)", a, b)
}

// parquetRelation renders read_parquet over an explicit file list, rooted at
// the configured storage path. An explicit list (rather than a glob) is used so
// live-generation selection is exact.
func parquetRelation(basePath string, files []string, hive bool) string {
	quoted := make([]string, len(files))
	for i, f := range files {
		quoted[i] = quoteSQL(filepath.Join(basePath, f))
	}
	opts := "union_by_name=true"
	if hive {
		opts = "hive_partitioning=true, " + opts
	}
	return fmt.Sprintf("read_parquet([%s], %s)", strings.Join(quoted, ", "), opts)
}

// emptyRelation is a zero-row, schema-typed relation for a table that has no
// files on disk yet, so a view still resolves and returns no rows instead of
// failing the whole query with a missing-glob error.
func emptyRelation(t manifest.Table, schema manifest.Schema) string {
	state := partition.ParseState(t.Partition)
	cols := make([]string, 0, len(schema.Columns)+1)
	for _, c := range schema.Columns {
		cols = append(cols, fmt.Sprintf("CAST(NULL AS %s) AS %s",
			duckType(c, state.Column == c.Name), quoteIdent(c.Name)))
	}
	if len(cols) == 0 {
		return "(SELECT NULL AS __empty WHERE false)"
	}
	return fmt.Sprintf("(SELECT %s WHERE false)", strings.Join(cols, ", "))
}

// duckType maps a manifest column to a DuckDB SQL type for the empty-table
// fallback. The partition column is a Hive key and reads back as DATE.
func duckType(c manifest.Column, isPartition bool) string {
	if isPartition {
		return "DATE"
	}
	switch c.ParquetType {
	case "INT32":
		return "INTEGER"
	case "INT64":
		return "BIGINT"
	case "FLOAT":
		return "REAL"
	case "DOUBLE", "DECIMAL":
		return "DOUBLE"
	case "BOOLEAN":
		return "BOOLEAN"
	case "BYTE_ARRAY":
		return "BLOB"
	default:
		return "VARCHAR"
	}
}
